Complete local Go example; the app itself does not execute it:
```go
package main

import (
"fmt"
"encoding/json"
)

type Session struct { Minutes int `json:"minutes"` }
func main() {
    var session Session
    err := json.Unmarshal([]byte(`{"minutes":15}`), &session)
    if err != nil { fmt.Println("invalid JSON"); return }
    if session.Minutes < 1 || session.Minutes > 60 { fmt.Println("invalid minutes"); return }
    fmt.Println(session.Minutes)
}
```

